local function new(c, p) local i = Instance.new(c); for k,v in pairs(p or {}) do i[k]=v end; return i end
local function corner(p, r) local c = Instance.new("UICorner"); c.CornerRadius = UDim.new(0, r or 8); c.Parent = p; return c end
local function tween(i, p, t) return TweenService:Create(i, TweenInfo.new(t or 0.2), p) end
local function getSafeGuiParent() if gethui then local ok, h = pcall(gethui); if ok and h then return h end end; local ok, c = pcall(function() return game:GetService("CoreGui") end); if ok and c then return c end; return LocalPlayer:WaitForChild("PlayerGui") end

local function createGlossyBorder(parent, thickness)
    local stroke = new("UIStroke", {Thickness = thickness or 2, Color = COLOR.White, Parent = parent})
    new("UIGradient", {Color = ColorSequence.new({ColorSequenceKeypoint.new(0, COLOR.White), ColorSequenceKeypoint.new(0.5, COLOR.GreyMed), ColorSequenceKeypoint.new(1, COLOR.Black)}), Rotation = 45, Parent = stroke})
end

local function createGlassEffect(parent)
    local glass = new("Frame", {Size = UDim2.new(1, 0, 0.5, 0), BackgroundColor3 = COLOR.White, BackgroundTransparency = 0.9, BorderSizePixel = 0, ZIndex = parent.ZIndex - 1, Parent = parent})
    corner(glass, 18)
    new("UIGradient", {Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.85), NumberSequenceKeypoint.new(1, 1)}), Rotation = 90, Parent = glass})
end

local function formatPrice(price) if not price or price <= 0 then return "—" end; if price >= 1000000000 then return string.format("%.1f M", price / 1000000000) elseif price >= 1000000 then return string.format("%d Jt", math.floor(price / 1000000)) elseif price >= 1000 then return string.format("%d K", math.floor(price / 1000)) end; return tostring(price) end
local function normalizeTruckName(str) str = string.lower(str or ""); str = str:gsub("[_%-%.]", " "); str = str:gsub("%s+", " "); return str:gsub("^%s+", ""):gsub("%s+$", "") end
local TRUCK_ALIASES = {["besi tua"] = {"besi tua", "besi lama", "besitua"}, ["fuso"] = {"fuso", "phuso"}, ["giga"] = {"giga", "g1ga"}, ["hino"] = {"hino", "hin0"}, ["trailer"] = {"trailer", "treler"}, ["l300"] = {"l300"}, ["dyna"] = {"dyna", "dina"}, ["rebeka"] = {"rebeka", "rebela"}, ["the fuso"] = {"the fuso", "fuso the great"}}
local function truckNameMatches(truckName, keyword) local haystack = normalizeTruckName(truckName); local n = normalizeTruckName(keyword); local vars = TRUCK_ALIASES[n] or {n}; for _, v in ipairs(vars) do if haystack:find(v, 1, true) then return true end end; return false end

local defaultConfig = {flySpeed = 60, guiX = 0.5, guiY = 0.5, toggleOffsetX = nil, toggleOffsetY = nil, savedPositions = {}, slotCounter = 0, destinationCache = {}, autoFarmDestination = nil, autoFarmTruck = nil, favoriteTrucks = {}, disabledFarmTrucks = {}, lastTruckTab = "Truk"}
local function saveConfig(d) if not writefile then return end; local ok, e = pcall(function() return HttpService:JSONEncode(d) end); if ok and e then pcall(function() writefile("bstsid_luxxyhub_config.json", e) end) end end
local function loadConfig() if not (isfile and readfile) then return defaultConfig end; local ok, c = pcall(function() if isfile("bstsid_luxxyhub_config.json") then return readfile("bstsid_luxxyhub_config.json") end end); if ok and c and c ~= "" then local ok2, d = pcall(function() return HttpService:JSONDecode(c) end); if ok2 and type(d) == "table" then for k, v in pairs(defaultConfig) do if d[k] == nil then d[k] = v end end; return d end end; return defaultConfig end
local userConfig = loadConfig()

local function startCarTool()
    if _G.BSTS_LuxxyHub_Cleanup then pcall(_G.BSTS_LuxxyHub_Cleanup) end
    local activeConnections, activeInstances = {}, {}
    _G.BSTS_LuxxyHub_Cleanup = function() for _, c in pairs(activeConnections) do pcall(function() c:Disconnect() end) end; for _, i in pairs(activeInstances) do pcall(function() if i and i.Parent then i:Destroy() end end) end; activeConnections, activeInstances = {}, {} end
    local function bind(sig, cb) local c = sig:Connect(cb); table.insert(activeConnections, c); return c end
    local function track(i) table.insert(activeInstances, i); return i end

    local pg = getSafeGuiParent(); if pg then local old = pg:FindFirstChild("BSTS_LuxxyHub"); if old then old:Destroy() end end
    local savedPositions, slotCounter = userConfig.savedPositions or {}, userConfig.slotCounter or 0
    local targetVehicleRoot, flyEnabled, flySpeed, flyBV, flyBG, farmEnabled, farmThread = nil, false, userConfig.flySpeed or 60, nil, nil, false, nil
    local playerModule, controls; pcall(function() playerModule = require(LocalPlayer:WaitForChild("PlayerScripts"):WaitForChild("PlayerModule")); controls = playerModule:GetControls() end)

    local saveDirty = false
    local function markSaveDirty() saveDirty = true end
    task.spawn(function() while true do task.wait(2); if saveDirty then saveDirty = false; userConfig.savedPositions, userConfig.slotCounter, userConfig.flySpeed = savedPositions, slotCounter, flySpeed; saveConfig(userConfig) end end end)

    local TOGGLE_SIZE, TOGGLE_MARGIN = 60, 10
    local function getViewport() local cam = workspace.CurrentCamera; if cam then return cam.ViewportSize end; return Vector2.new(1280, 720) end
    local function isTogglePositionValid(x, y) if not x or not y or type(x) ~= "number" or type(y) ~= "number" then return false end; local vp = getViewport(); if x + TOGGLE_SIZE < 20 or y + TOGGLE_SIZE < 20 or x > vp.X - 20 or y > vp.Y - 20 then return false end; return true end
    local function clampTogglePosition(x, y) local vp = getViewport(); local maxX, maxY = vp.X - TOGGLE_SIZE - TOGGLE_MARGIN, vp.Y - TOGGLE_SIZE - TOGGLE_MARGIN; return math.clamp(x, TOGGLE_MARGIN, math.max(TOGGLE_MARGIN, maxX)), math.clamp(y, TOGGLE_MARGIN, math.max(TOGGLE_MARGIN, maxY)) end
    local startX, startY = 15, 100; if isTogglePositionValid(userConfig.toggleOffsetX, userConfig.toggleOffsetY) then startX, startY = userConfig.toggleOffsetX, userConfig.toggleOffsetY end

    local function findNearestCar() local char = LocalPlayer.Character; if not char then return nil end; local hrp = char:FindFirstChild("HumanoidRootPart"); if not hrp then return nil end; local nearest, shortest = nil, math.huge; for _, o in pairs(workspace:GetDescendants()) do if o:IsA("VehicleSeat") then local d = (o.Position - hrp.Position).Magnitude; if d < shortest then shortest = d; local m = o:FindFirstAncestorOfClass("Model") or o.Parent; local root = m; local c = m; while c and c.Parent and c.Parent ~= workspace do c = c.Parent; if c:IsA("Model") then root = c end end; nearest = root end end end; return nearest end
    local function getDrivenVehicle() local char = LocalPlayer.Character; if not char then return nil, {} end; local hum = char:FindFirstChildOfClass("Humanoid"); if not hum then return nil, {} end; local seat = hum.SeatPart; if not seat then return nil, {} end; local names = {}; local c = seat; while c and c ~= game do if c.Name and c.Name ~= "" then table.insert(names, c.Name) end; c = c.Parent end; local top = seat; local c2 = seat; while c2 and c2.Parent and c2.Parent ~= workspace do c2 = c2.Parent; if c2:IsA("Model") then top = c2 end end; return top, names end
    
    local function isTruckDisabled(name) local n = normalizeTruckName(name); for _, d in ipairs(userConfig.disabledFarmTrucks or {}) do if normalizeTruckName(d) == n then return true end end; return false end
    local function isDrivingFarmTruck() local v, names = getDrivenVehicle(); if not v or #names == 0 then return false, nil end; if userConfig.autoFarmTruck then for _, n in ipairs(names) do if truckNameMatches(n, userConfig.autoFarmTruck) then return true, v end end end; for _, n in ipairs(names) do local nNorm = normalizeTruckName(n); for _, kw in ipairs(CONFIG.FarmTruckWhitelist) do if not isTruckDisabled(kw) and truckNameMatches(nNorm, kw) then local isT = nNorm:find("trailer", 1, true) and not nNorm:find("hino", 1, true) and not nNorm:find("besi", 1, true) and not nNorm:find("giga", 1, true) and not nNorm:find("semi", 1, true); if not isT then return true, v end end end end; return false, v end

    local function teleportCarToPos(pos) if not pos then return end; local v = getDrivenVehicle(); v = v or targetVehicleRoot; if not v then return end; local p = v.PrimaryPart or v:FindFirstChildWhichIsA("BasePart"); if not p then for _, d in pairs(v:GetDescendants()) do if d:IsA("BasePart") then p = d break end end end; if not p then return end; local parts, rels = {}, {}; for _, b in pairs(v:GetDescendants()) do if b:IsA("BasePart") then table.insert(parts, b); rels[b] = p.CFrame:ToObjectSpace(b.CFrame) end end; for _, b in pairs(parts) do b.Anchored = true end; p.CFrame = CFrame.new(pos + Vector3.new(0, 3, 0)); for b, r in pairs(rels) do b.CFrame = p.CFrame:ToWorldSpace(r) end; task.wait(0.1); for _, b in pairs(parts) do pcall(function() if b:CanSetNetworkOwnership() then b:SetNetworkOwner(LocalPlayer) end end) end; for _, b in pairs(parts) do b.Anchored = false end end
    local function teleportPlayerToPos(pos) if not pos then return end; local char = LocalPlayer.Character; if not char then return end; local hrp = char:FindFirstChild("HumanoidRootPart"); if hrp then hrp.CFrame = CFrame.new(pos + Vector3.new(0, 4, 0)) end end

    local function scanDest() local f = workspace:FindFirstChild(CONFIG.DestinationFolder); if not f then return {} end; local res = {}; for _, d in ipairs(f:GetChildren()) do if d:IsA("Model") then local z = d:FindFirstChild("Zone", true); if z and z:IsA("BasePart") then local n = d.Name; if n:sub(1, #CONFIG.DestinationPrefix) == CONFIG.DestinationPrefix then n = n:sub(#CONFIG.DestinationPrefix + 1) end; table.insert(res, {name = n, fullName = d.Name, position = z.Position}) end end end; return res end
    local function getCachedDest() local c = userConfig.destinationCache and userConfig.destinationCache[tostring(game.PlaceId)] or {}; local out = {}; for _, v in ipairs(c) do table.insert(out, {name = v.name, fullName = v.fullName, position = Vector3.new(v.x, v.y, v.z)}) end; return out end
    local function teleportToDest(name) local d = scanDest(); if #d == 0 then d = getCachedDest() end; for _, v in ipairs(d) do if v.name == name or v.fullName == name then teleportCarToPos(v.position); return true end end; return false end

    local function scanLoads() local f = workspace:FindFirstChild(CONFIG.LoadFolder) or workspace; local res, seen = {}, {}; for _, o in pairs(f:GetDescendants()) do if o:IsA("ProximityPrompt") and string.find(string.lower(o.ActionText or ""), string.lower(CONFIG.LoadPromptAction), 1, true) then local p = o.Parent; local b = p and (p:IsA("BasePart") and p or p:FindFirstChildWhichIsA("BasePart")); if b then local n = o.ObjectText or "Unknown"; local k = n .. b.Position.X .. b.Position.Z; if not seen[k] then seen[k] = true; table.insert(res, {name = n, prompt = o, position = b.Position, hold = o.HoldDuration or 0.5, dist = o.MaxActivationDistance or 10}) end end end end end; return res end
    local function farLoad(name) local loads = scanLoads(); local t; for _, l in ipairs(loads) do if string.lower(l.name) == string.lower(name) then t = l break end end; if not t then return false end; local v = getDrivenVehicle() or targetVehicleRoot; if not v then return false end; local char = LocalPlayer.Character; local hrp = char and char:FindFirstChild("HumanoidRootPart"); if not hrp then return false end; local origP, origV = hrp.CFrame, (v.PrimaryPart or v:FindFirstChildWhichIsA("BasePart")); if not origV then return false end; local origVCF = origV.CFrame; local dir = (origVCF.Position - t.position).Unit; if dir.Magnitude < 0.1 then dir = Vector3.new(0,0,1) end; local tp = t.position + dir * CONFIG.FarLoadOffset; tp = Vector3.new(tp.X, t.position.Y + 3, tp.Z); local parts, rels = {}, {}; for _, b in pairs(v:GetDescendants()) do if b:IsA("BasePart") then table.insert(parts, b); rels[b] = origV.CFrame:ToObjectSpace(b.CFrame) end end; for _, b in pairs(parts) do b.Anchored = true end; origV.CFrame = CFrame.new(tp); for b, r in pairs(rels) do b.CFrame = origV.CFrame:ToWorldSpace(r) end; hrp.CFrame = CFrame.new(tp); task.wait(0.1); if fireproximityprompt then pcall(function() fireproximityprompt(t.prompt) end) else pcall(function() t.prompt:InputHoldBegin(); task.wait(t.hold + 0.1); t.prompt:InputHoldEnd() end) end; task.wait(t.hold + 0.4); origV.CFrame = origVCF; for b, r in pairs(rels) do b.CFrame = origV.CFrame:ToWorldSpace(r) end; hrp.CFrame = origP; task.wait(0.1); for _, b in pairs(parts) do pcall(function() if b:CanSetNetworkOwnership() then b:SetNetworkOwner(LocalPlayer) end end) end; for _, b in pairs(parts) do b.Anchored = false end; return true end

    local function loadTrucks() local tr = {}; local RS = game:GetService("ReplicatedStorage"); local function merge(n, k) local c = RS:FindFirstChild(n); if c then local ok, d = pcall(require, c); if ok and type(d) == "table" then for nm, v in pairs(d) do tr[nm] = tr[nm] or {}; tr[nm][k] = v end end end end; merge("TruckPriceConfig", "price"); merge("TruckPhotoConfig", "photo"); merge("TruckPassConfig", "passId"); for _, n in ipairs({"BESI TUA", "Trailer Besi Tua", "Canter Horeg", "DYNA", "Fuso Kayu", "Fuso Panjang", "FUSO YANG HEBAT", "GIGA", "GIGA TRAILER", "HINO", "Trailer HINO", "L300", "L300 HOREG", "Ragasa Kuning", "REDEKA", "Trailer Pencocokan", "SEMI TRAILER", "Trailer Lowboy", "FUSO THE GREAT", "FUSO LONG", "FUSO KAYU", "REBEKA"}) do if not tr[n] then tr[n] = {} end end; local arr = {}; for n, i in pairs(tr) do table.insert(arr, {name = n, price = tonumber(i.price) or 0, photo = i.photo, passId = i.passId}) end; table.sort(arr, function(a, b) if a.price ~= b.price then return a.price > b.price end return a.name < b.name end); return arr end
    local function isTrailer(name) local n = string.lower(name); for _, k in ipairs(CONFIG.TrailerNames) do if n:find(k, 1, true) then return true end end; return false end
    local function spawnTruck(name) local RS = game:GetService("ReplicatedStorage"); local f = RS:FindFirstChild(CONFIG.TruckSpawnerFolder); if not f then return false end; local r = f:FindFirstChild(CONFIG.SpawnTruckRemote); if not r then return false end; local ok = pcall(function() r:FireServer(name) end); return ok end
    local function removeTrucks() local RS = game:GetService("ReplicatedStorage"); local f = RS:FindFirstChild(CONFIG.TruckSpawnerFolder); if not f then return false end; local r = f:FindFirstChild(CONFIG.RemoveTruckRemote); if not r then return false end; local ok = pcall(function() r:FireServer() end); return ok end
    
    local function autoSpawnAndSit(name, lbl) if not name then return false end; if lbl then lbl.Text = "🗑 Menghapus truck..." end; removeTrucks(); task.wait(1.5); if lbl then lbl.Text = "🚀 Spawn " .. name .. "..." end; spawnTruck(name); task.wait(3); local char = LocalPlayer.Character; local hrp = char and char:FindFirstChild("HumanoidRootPart"); local hum = char and char:FindFirstChildOfClass("Humanoid"); if not hrp or not hum then return false end; local seat, dist = nil, math.huge; for _, o in pairs(workspace:GetDescendants()) do if o:IsA("VehicleSeat") then local d = (o.Position - hrp.Position).Magnitude; if d < dist then dist = d seat = o end end end; if seat then if lbl then lbl.Text = "🧍 Duduk..." end; hrp.CFrame = seat.CFrame * CFrame.new(0, 3, 0); task.wait(0.5); hum.Sit = true; task.wait(1); if hum.SeatPart == seat then return true else hrp.CFrame = seat.CFrame; task.wait(0.2); hum.Sit = true; task.wait(1); return hum.SeatPart == seat end end; return false end

    local function toggleFly() flyEnabled = not flyEnabled; local char = LocalPlayer.Character; if not char then return end; local hrp = char:FindFirstChild("HumanoidRootPart"); local hum = char:FindFirstChildOfClass("Humanoid"); if not hrp or not hum then return end; if flyEnabled then hum.PlatformStand = true; flyBV = Instance.new("BodyVelocity", hrp); flyBV.MaxForce = Vector3.new(math.huge, math.huge, math.huge); flyBV.Velocity = Vector3.new(0,0,0); flyBG = Instance.new("BodyGyro", hrp); flyBG.MaxTorque = Vector3.new(math.huge, math.huge, math.huge); flyBG.P = 10000; flyBG.D = 100 else if flyBV then flyBV:Destroy() end; if flyBG then flyBG:Destroy() end; hum.PlatformStand = false end end

    local function startFarm(lbl) if farmEnabled then return end; farmEnabled = true; farmThread = task.spawn(function() while farmEnabled do local isD = isDrivingFarmTruck(); if not isD then local t = userConfig.autoFarmTruck or CONFIG.FarmTruckWhitelist[1]; if not t then task.wait(3) else autoSpawnAndSit(t, lbl); task.wait(1) end else if lbl then lbl.Text = "🌾 [1/6] TP Slot 19..." end; teleportCarToPos(savedPositions[2] and savedPositions[2].pos or DEFAULT_SLOT19); task.wait(2); if lbl then lbl.Text = "🌾 [2/6] Muat..." end; if fireproximityprompt then local p = workspace:FindFirstChild("SEMUA MUATAN") and workspace.SEMUA MUATAN:GetDescendants() or {}; for _, o in pairs(p) do if o:IsA("ProximityPrompt") and o.Enabled then pcall(function() fireproximityprompt(o) end); break end end end; task.wait(2.5); if not farmEnabled then break end; if lbl then lbl.Text = "🌾 [3/6] TP Slot 20..." end; teleportCarToPos(savedPositions[1] and savedPositions[1].pos or DEFAULT_SLOT20); task.wait(2); if lbl then lbl.Text = "🌾 [4/6] Muat..." end; if fireproximityprompt then local p = workspace:FindFirstChild("SEMUA MUATAN") and workspace.SEMUA MUATAN:GetDescendants() or {}; for _, o in pairs(p) do if o:IsA("ProximityPrompt") and o.Enabled then pcall(function() fireproximityprompt(o) end); break end end end; task.wait(2.5); if not farmEnabled then break end; local d = userConfig.autoFarmDestination; if d then if lbl then lbl.Text = "💰 [5/6] TP Destinasi..." end; teleportToDest(d); task.wait(3); if lbl then lbl.Text = "💰 [6/6] Tunggu bayaran..." end; task.wait(2) else task.wait(2) end end end end) end
    local function stopFarm() farmEnabled = false; if farmThread then pcall(function() task.cancel(farmThread) end); farmThread = nil end end

    local cam = workspace.CurrentCamera
    local vp = (cam and cam.ViewportSize) or Vector2.new(1280, 720)
    local guiW = math.clamp(340, math.min(260, vp.X - 40), math.max(math.min(260, vp.X - 40), vp.X - 40))
    local guiH = math.clamp(600, math.min(420, vp.Y - 60), math.max(math.min(420, vp.Y - 60), vp.Y - 60))
    local ScreenGui = track(new("ScreenGui", {Name = "BSTS_LuxxyHub", ResetOnSpawn = false, ZIndexBehavior = Enum.ZIndexBehavior.Sibling, IgnoreGuiInset = true, DisplayOrder = 100, Parent = getSafeGuiParent()}))
    local ToggleWrapper = track(new("Frame", {Name = "ToggleWrapper", AnchorPoint = Vector2.new(0, 0), Size = UDim2.new(0, 60, 0, 60), Position = UDim2.new(0, startX, 0, startY), BackgroundTransparency = 1, ZIndex = 200, Parent = ScreenGui}))
    local ToggleBtn = new("TextButton", {Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = COLOR.Black, BorderSizePixel = 0, Text = "", AutoButtonColor = false, Active = true, ZIndex = 202, Parent = ToggleWrapper})
    corner(ToggleBtn, 30); createGlossyBorder(ToggleBtn, 2); createGlassEffect(ToggleBtn); new("ImageLabel", {Size = UDim2.new(0.75, 0, 0.75, 0), Position = UDim2.new(0.5, 0, 0.5, 0), AnchorPoint = Vector2.new(0.5, 0.5), BackgroundTransparency = 1, Image = IMG_TOGGLE, ImageColor3 = COLOR.White, ScaleType = Enum.ScaleType.Fit, ZIndex = 203, Parent = ToggleBtn})

    local isDragging, dragStartPos, dragStartInput, hasMoved = false, nil, nil, false
    bind(ToggleBtn.InputBegan, function(i) if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then isDragging = true; hasMoved = false; dragStartInput = Vector2.new(i.Position.X, i.Position.Y); dragStartPos = ToggleWrapper.Position end end)
    bind(UserInputService.InputChanged, function(i) if not isDragging then return end; if i.UserInputType == Enum.UserInputType.MouseMovement or i.UserInputType == Enum.UserInputType.Touch then local curr = Vector2.new(i.Position.X, i.Position.Y); local delta = curr - dragStartInput; if delta.Magnitude > 5 then hasMoved = true end; if hasMoved then local cx, cy = clampTogglePosition(dragStartPos.X.Offset + delta.X, dragStartPos.Y.Offset + delta.Y); ToggleWrapper.Position = UDim2.new(0, cx, 0, cy) end end end)
    bind(UserInputService.InputEnded, function(i) if i.UserInputType == Enum.UserInputType.MouseButton1 or i.UserInputType == Enum.UserInputType.Touch then if isDragging and hasMoved then local cx, cy = clampTogglePosition(ToggleWrapper.Position.X.Offset, ToggleWrapper.Position.Y.Offset); ToggleWrapper.Position = UDim2.new(0, cx, 0, cy); if isTogglePositionValid(cx, cy) then userConfig.toggleOffsetX, userConfig.toggleOffsetY = cx, cy; markSaveDirty() end end; isDragging = false; dragStartPos = nil; dragStartInput = nil end end)

    local MainWrapper = track(new("Frame", {Name = "MainWrapper", AnchorPoint = Vector2.new(0.5, 0.5), Size = UDim2.new(0, guiW, 0, guiH), Position = UDim2.new(userConfig.guiX or 0.5, 0, userConfig.guiY or 0.5, 0), BackgroundTransparency = 1, Visible = false, ZIndex = 99, Parent = ScreenGui}))
    local MainFrame = track(new("Frame", {Name = "MainFrame", Size = UDim2.new(1, 0, 1, 0), BackgroundColor3 = COLOR.BG, BorderSizePixel = 0, Active = true, Draggable = true, ClipsDescendants = true, ZIndex = 100, Parent = MainWrapper}))
    corner(MainFrame, 18); createGlossyBorder(MainFrame, 2); createGlassEffect(MainFrame)
    bind(MainFrame:GetPropertyChangedSignal("Position"), function() if MainWrapper.Visible then userConfig.guiX, userConfig.guiY = MainWrapper.Position.X.Scale, MainWrapper.Position.Y.Scale; markSaveDirty() end end)

    local Header = new("Frame", {Size = UDim2.new(1,0,0,50), BackgroundColor3 = COLOR.Black, BackgroundTransparency = 0.6, BorderSizePixel = 0, Parent = MainFrame}); corner(Header, 18)
